const CACHE='yuan-weather-v180';const ASSETS=['./','./index.html','./style.css','./app.mjs','./core.mjs','./i18n.mjs','./timezones.mjs','./google-route.mjs','./google-weather.mjs','./google-panel.mjs','./route-import.mjs','./fflate.mjs','./sax.mjs','./route-stream.mjs','./route-filter.mjs','./route-worker.mjs','./route-client.mjs','./manifest.webmanifest','./icon-192.png','./icon-512.png'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{let u=new URL(e.request.url);if(u.origin!==self.location.origin||e.request.method!=='GET')return;e.respondWith(fetch(e.request).then(r=>{if(r.ok&&!r.redirected&&(!r.headers.get('content-type')?.includes('text/html')||u.pathname.endsWith('/')||u.pathname.endsWith('index.html'))){let copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request).then(r=>r||new Response('Offline',{status:503}))))});
